import re, html
def norm(s): return re.sub(r'\s+',' ',html.unescape(s))
def chk(fn, needles):
    t=norm(open(fn,encoding='utf-8',errors='replace').read())
    low=t.lower()
    for label,nd in needles.items():
        n=norm(nd).lower()
        i=low.find(n)
        print(fn, label, 'FOUND' if i>=0 else 'MISSING')
        if i>=0:
            print('   ...', t[max(0,i-200):i+len(n)+300].replace('\n',' '), '...')
